import fs from "node:fs";

import type { EngineProfile, PdModeProfile } from "../../src/api.ts";

// The engine profiles as the server serves them (GET /api/v1/engines,
// regenerated by internal/server/api/engines_fixture_test.go), so a PD test
// sees the mode catalog the server really publishes rather than one it wrote.
export const engineProfiles = JSON.parse(
  fs.readFileSync(new URL("../fixtures/engines.json", import.meta.url), "utf8"),
) as EngineProfile[];

export function fixturePdModes(engine: string): PdModeProfile[] {
  return engineProfiles.find((profile) => profile.name === engine)?.pd_modes ?? [];
}
